import{_ as t,o,c as i,a0 as a}from"./chunks/framework.DYS8d9tm.js";const g=JSON.parse('{"title":"WealthFam Ecosystem: The Architectural Manifesto","description":"","frontmatter":{},"headers":[],"relativePath":"technical/architecture/workspace_repos.md","filePath":"technical/architecture/workspace_repos.md"}'),n={name:"technical/architecture/workspace_repos.md"};function r(s,e,l,c,d,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="wealthfam-ecosystem-the-architectural-manifesto" tabindex="-1">WealthFam Ecosystem: The Architectural Manifesto <a class="header-anchor" href="#wealthfam-ecosystem-the-architectural-manifesto" aria-label="Permalink to &quot;WealthFam Ecosystem: The Architectural Manifesto&quot;">​</a></h1><p>This document provides an exhaustive reference for the WealthFam multi-repository workspace. It is the primary training data for AI agents and the transition guide for human architects.</p><hr><h2 id="_1-repository-taxonomy-governance" tabindex="-1">1. Repository Taxonomy &amp; Governance <a class="header-anchor" href="#_1-repository-taxonomy-governance" aria-label="Permalink to &quot;1. Repository Taxonomy &amp; Governance&quot;">​</a></h2><p>The workspace is divided into <strong>Source Repositories</strong> (logic owners) and <strong>Operational Repositories</strong> (deployment &amp; testing).</p><h3 id="_1-1-source-repositories-the-real-code" tabindex="-1">1.1 Source Repositories (The &quot;Real&quot; Code) <a class="header-anchor" href="#_1-1-source-repositories-the-real-code" aria-label="Permalink to &quot;1.1 Source Repositories (The &quot;Real&quot; Code)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Repository</th><th style="text-align:left;">Role</th><th style="text-align:left;">Key Directories</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>backend</code></strong></td><td style="text-align:left;">Core Business Engine</td><td style="text-align:left;"><code>/app/modules/finance</code>, <code>/app/modules/auth</code>, <code>/app/core/telemetry.py</code> (Shipper), <code>/app/api/v1/router.py</code> (Mobile/Telemetry Proxy)</td></tr><tr><td style="text-align:left;"><strong><code>frontend</code></strong></td><td style="text-align:left;">Desktop Client</td><td style="text-align:left;"><code>/src/components/</code>, <code>/src/services/telemetry.ts</code>, <code>/src/api/client.ts</code></td></tr><tr><td style="text-align:left;"><strong><code>parser</code></strong></td><td style="text-align:left;">Ingestion Engine</td><td style="text-align:left;"><code>/parsers/</code> (Regex &amp; CAS), <code>/core/pipeline.py</code>, <code>/core/telemetry.py</code> (Shipper)</td></tr><tr><td style="text-align:left;"><strong><code>Admin-Backend</code></strong></td><td style="text-align:left;">Operational Control Plane (REST Proxy + DuckDB)</td><td style="text-align:left;"><code>/app/api/telemetry.py</code>, <code>/app/api/parsers.py</code>, <code>/app/api/brands.py</code>, <code>/app/services/prober.py</code></td></tr><tr><td style="text-align:left;"><strong><code>Admin-Web</code></strong></td><td style="text-align:left;">Enterprise Admin Console</td><td style="text-align:left;"><code>/src/views/DashboardView.vue</code>, <code>/src/views/ParsersView.vue</code>, <code>/src/views/BrandsView.vue</code></td></tr><tr><td style="text-align:left;"><strong><code>mobile_app</code></strong></td><td style="text-align:left;">On-the-go Tracking</td><td style="text-align:left;"><code>/lib/core/services/telemetry_service.dart</code>, <code>/lib/core/services/foreground_task_handler.dart</code></td></tr></tbody></table><h3 id="_1-2-operational-repositories-the-glue" tabindex="-1">1.2 Operational Repositories (The &quot;Glue&quot;) <a class="header-anchor" href="#_1-2-operational-repositories-the-glue" aria-label="Permalink to &quot;1.2 Operational Repositories (The &quot;Glue&quot;)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Repository</th><th style="text-align:left;">Role</th><th style="text-align:left;">Critical Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>Demo (Render IO)</code></strong></td><td style="text-align:left;">Deployment Proxy</td><td style="text-align:left;"><code>nginx.conf</code>, <code>render.yaml</code>, <code>sync_to_demo.sh</code></td></tr><tr><td style="text-align:left;"><strong><code>Test Suite</code></strong></td><td style="text-align:left;">Quality Gatekeeper</td><td style="text-align:left;"><code>/modules/auth</code>, <code>/modules/finance</code>, <code>conftest.py</code></td></tr><tr><td style="text-align:left;"><strong><code>Infra</code></strong></td><td style="text-align:left;">Local Dev / Docker</td><td style="text-align:left;"><code>docker-compose.yml</code>, <code>secrets.example.env</code></td></tr><tr><td style="text-align:left;"><strong><code>Docs</code></strong></td><td style="text-align:left;">Knowledge Hub</td><td style="text-align:left;"><code>system_overview.md</code>, <code>workspace_repos.md</code></td></tr></tbody></table><hr><h2 id="_2-technical-philosophy-core-patterns" tabindex="-1">2. Technical Philosophy &amp; Core Patterns <a class="header-anchor" href="#_2-technical-philosophy-core-patterns" aria-label="Permalink to &quot;2. Technical Philosophy &amp; Core Patterns&quot;">​</a></h2><h3 id="_2-1-the-ironclad-transaction-pattern" tabindex="-1">2.1 The &quot;Ironclad&quot; Transaction Pattern <a class="header-anchor" href="#_2-1-the-ironclad-transaction-pattern" aria-label="Permalink to &quot;2.1 The &quot;Ironclad&quot; Transaction Pattern&quot;">​</a></h3><p>With the migration to <strong>PostgreSQL</strong> as the core backend storage, database interactions support native ACID transaction management:</p><ul><li><strong>ACID Concurrency</strong>: Thanks to PostgreSQL&#39;s native transaction isolation and concurrency support, standard write operations do not require any application-level write locks. The custom <code>db_write_lock</code> is no longer used in the backend.</li><li><strong>Atomic Snapshots</strong>: When a financial balance is updated, the system automatically creates a <code>BalanceSnapshot</code> entry. This allows for historical auditing and &quot;Time Machine&quot; financial views without recalculating thousands of transactions.</li></ul><h3 id="_2-2-tenant-isolation-security" tabindex="-1">2.2 Tenant Isolation &amp; Security <a class="header-anchor" href="#_2-2-tenant-isolation-security" aria-label="Permalink to &quot;2.2 Tenant Isolation &amp; Security&quot;">​</a></h3><p>WealthFam is built on a <strong>Multi-Tenant Architecture</strong>:</p><ul><li><strong>Tenant ID</strong>: Every table (except system-wide metadata) contains a <code>tenant_id</code> column.</li><li><strong>JWT Scoping</strong>: Authentication tokens include the <code>tenant_id</code>. The <code>get_current_user</code> dependency in the backend automatically filters all queries by the user&#39;s tenant, preventing cross-family data leaks.</li><li><strong>Password Hashing</strong>: We use <code>bcrypt</code> for hashing. The field name in the database is strictly <code>password_hash</code>.</li></ul><hr><h2 id="_3-communication-proxy-architecture" tabindex="-1">3. Communication &amp; Proxy Architecture <a class="header-anchor" href="#_3-communication-proxy-architecture" aria-label="Permalink to &quot;3. Communication &amp; Proxy Architecture&quot;">​</a></h2><h3 id="_3-1-the-nginx-controller" tabindex="-1">3.1 The &quot;Nginx Controller&quot; <a class="header-anchor" href="#_3-1-the-nginx-controller" aria-label="Permalink to &quot;3.1 The &quot;Nginx Controller&quot;&quot;">​</a></h3><p>In the Monolith Docker &amp; <code>Demo (Render IO)</code> deployments, Nginx acts as the unified ingress controller with port-isolated admin routing:</p><ul><li><strong>Port 80 (Client Ingress)</strong>: <ul><li><strong>Frontend</strong>: <code>/</code> → <code>Web-App</code> static SPA (zero direct <code>/parser</code> exposure).</li><li><strong>API Routing</strong>: <code>/api</code> → Proxied to FastAPI Backend (Port 8000), which handles internal calls to <code>Parser</code> (<code>PARSER_SERVICE_URL</code>), client telemetry proxying (<code>/api/v1/telemetry/ingest</code>), and anonymized reporting proxies to <code>Admin-Backend</code> (<code>ADMIN_SERVICE_URL</code>).</li><li><strong>WebSocket Routing</strong>: <code>/ws/</code> → Proxied to FastAPI Backend WebSockets (Port 8000).</li><li><strong>Telemetry Routing</strong>: <code>/telemetry/</code> → Proxied to Admin-Backend write-only anonymous ingestion (Port 8002).</li><li><strong>Health Checks</strong>: Monitors <code>GET /health</code> against the underlying backend service.</li></ul></li><li><strong>Mobile &amp; Client Telemetry Ingestion Policy</strong>: <ul><li><strong>Web App</strong>: Flushes anonymous route navigation latencies, API error rates, and unhandled Vue exceptions via <code>/telemetry/ingest</code> (using <code>sendBeacon</code> on page unload) with explicit opt-in preference toggles.</li><li><strong>Mobile App</strong>: Emits app lifecycle transitions, foreground SMS heartbeats, sync latencies, and sanitized crash signatures through the Backend proxy (<code>/api/v1/telemetry/ingest</code>), requiring zero secondary URL configurations. Features offline-first <code>SharedPreferences</code> queuing (FIFO 100 max) that retains data across network outages and retries on reconnection. Supports independent cloud hardcoding via <code>TelemetryService.dedicatedTelemetryUrl</code>.</li></ul></li><li><strong>Port 8080 (Dedicated Port-Isolated Admin Ingress)</strong>: <ul><li><strong>Admin UI</strong>: <code>/</code> → <code>Admin-Web</code> static SPA.</li><li><strong>Admin API &amp; WebSocket Logs</strong>: <code>/admin-api/</code> → Proxied to <code>Admin-Backend</code> (Port 8002 <code>/v1/</code>).</li></ul></li></ul><h3 id="_3-2-subpath-routing-policy" tabindex="-1">3.2 Subpath Routing Policy <a class="header-anchor" href="#_3-2-subpath-routing-policy" aria-label="Permalink to &quot;3.2 Subpath Routing Policy&quot;">​</a></h3><p>To maintain compatibility across Localhost, Docker, and Cloud (Render), we use <strong>Relative Paths</strong> in all test and frontend calls.</p><ul><li><strong>Example</strong>: Requesting <code>/auth/login</code> while the base URL is <code>https://wealthfam.com/api/v1/</code> will correctly resolve to <code>/api/v1/auth/login</code>.</li></ul><hr><h2 id="_4-deployment-pipeline-the-official-demo-sync-flow" tabindex="-1">4. Deployment Pipeline (The Official Demo Sync Flow) <a class="header-anchor" href="#_4-deployment-pipeline-the-official-demo-sync-flow" aria-label="Permalink to &quot;4. Deployment Pipeline (The Official Demo Sync Flow)&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>This pipeline is designed exclusively for the <strong>Official WealthFam Demo</strong> hosted on Render. User deployments for personal use should follow the <strong>Local Docker</strong> pathway.</p></div><p>We use a &quot;Staging Area&quot; strategy for the official cloud demonstration:</p><ol><li>Developer modifies <strong>Source Repos</strong> (<code>backend</code>, <code>parser</code>).</li><li>The <code>sync_to_demo.sh</code> script (in the <code>Demo (Render IO)</code> repo) is executed.</li><li>This script wipes the local subdirectories in the <code>Demo</code> repo and clones/copies the fresh code from the <code>backend</code>, <code>parser</code>, and <code>AI Agent</code> directories.</li><li>The <code>Demo</code> repo is then pushed to GitHub, triggering Render.io to build the multi-container environment.</li></ol><hr><h2 id="_5-testing-validation-strategy" tabindex="-1">5. Testing &amp; Validation Strategy <a class="header-anchor" href="#_5-testing-validation-strategy" aria-label="Permalink to &quot;5. Testing &amp; Validation Strategy&quot;">​</a></h2><p>The <strong><code>Test Suite</code></strong> is the ultimate truth for system health.</p><ul><li><strong>Cloud-Aware Testing</strong>: The suite detects if it is running in GitHub Actions and automatically switches to a <code>CIClient</code>.</li><li><strong>Path Stripping</strong>: The <code>CIClient</code> is designed to strip leading slashes from request URLs, forcing <code>httpx</code> to append paths to the <code>/api/v1</code> or <code>/parser</code> base URLs instead of replacing them. This is critical for hittingproxied subpaths.</li></ul><hr><h2 id="_6-guidelines-for-future-ai-agents" tabindex="-1">6. Guidelines for Future AI Agents <a class="header-anchor" href="#_6-guidelines-for-future-ai-agents" aria-label="Permalink to &quot;6. Guidelines for Future AI Agents&quot;">​</a></h2><ol><li><strong>Stop &amp; Search</strong>: Before refactoring a service, check the <code>Docs/</code> repo for existing patterns (e.g., how to handle PostgreSQL concurrency and indexes).</li><li><strong>Edit Source First</strong>: Never apply architectural changes directly to the <code>Demo</code> folder. They will be lost on the next sync.</li><li><strong>Validate Locally</strong>: Run <code>docker-compose up</code> from the <code>Infra</code> repo to ensure your changes work in a containerized environment before pushing to the cloud.</li><li><strong>Update This Doc</strong>: If you change a core pattern (e.g., moving from DuckDB to Postgres), update this Manifesto immediately.</li></ol><hr><h2 id="_7-documentation-engineering" tabindex="-1">7. Documentation Engineering <a class="header-anchor" href="#_7-documentation-engineering" aria-label="Permalink to &quot;7. Documentation Engineering&quot;">​</a></h2><p>WealthFam follows a <strong>Documentation-as-Code</strong> philosophy. Our technical documentation is treated with the same rigor as our application code.</p><h3 id="_7-1-the-docs-stack" tabindex="-1">7.1 The Docs Stack <a class="header-anchor" href="#_7-1-the-docs-stack" aria-label="Permalink to &quot;7.1 The Docs Stack&quot;">​</a></h3><ul><li><strong>Engine</strong>: We use <strong>VitePress</strong> to generate a fast, optimized, and SEO-friendly static site.</li><li><strong>Source</strong>: All markdown files live in the <code>Docs</code> repository.</li><li><strong>Automation</strong>: <ul><li>Documentation is automatically rebuilt on every push to the <code>Docs</code> repository.</li><li>A GitHub Action (<code>.github/workflows/deploy.yml</code>) handles the build and syncs the static assets to the <strong><code>wealthfam.github.io</code></strong> repository for public hosting.</li></ul></li></ul><h3 id="_7-2-navigation-structure" tabindex="-1">7.2 Navigation &amp; Structure <a class="header-anchor" href="#_7-2-navigation-structure" aria-label="Permalink to &quot;7.2 Navigation &amp; Structure&quot;">​</a></h3><ul><li><strong>Configuration</strong>: The sidebar and top-level navigation are managed via <code>.vitepress/config.mts</code>.</li><li><strong>Content Types</strong>: <ul><li><code>/technical/</code>: Deep dives into backend, schema, and mobile logic.</li><li><code>/user/</code>: End-user guides and feature walkthroughs.</li><li><code>/deployment/</code>: Infrastructure and dev-ops instructions.</li><li><code>/Management/</code>: Governance, RFCs, and contribution guidelines.</li></ul></li></ul><h3 id="_7-3-guidelines-for-updates" tabindex="-1">7.3 Guidelines for Updates <a class="header-anchor" href="#_7-3-guidelines-for-updates" aria-label="Permalink to &quot;7.3 Guidelines for Updates&quot;">​</a></h3><ul><li>When a new microservice is added, it <strong>must</strong> be documented in this <code>Docs</code> repository.</li><li>Use internal linking (e.g., <code>[Link](./other_doc.md)</code>) for seamless cross-referencing.</li><li>Ensure all images are stored in <code>/Media/</code> and referenced with absolute paths within the documentation site.</li></ul><hr><div align="center"> *Made with ❤️ by WGLabz* </div>',48)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
